class Solution(object):
    def catMouseGame(self, graph):
        """
        :type graph: List[List[int]]
        :rtype: int
        """
        # dp[i][j][k]
        # i: position of mouse
        # j: position of cat
        # k: number of steps
        # 0: draw, 1: mouse win, 2: cat win
        n = len(graph)
        dp = [[[-1 for _ in range(2 * n)] for _ in range(n)] for _ in range(n)]

        def get_result(mouse, cat, turns):
            if turns == 2 * n:
                return 0
            if dp[mouse][cat][turns] != -1:
                return dp[mouse][cat][turns]
            if mouse == 0:
                ans = 1
            elif mouse == cat:
                ans = 2
            else:
                if turns % 2 == 0:
                    cur_node = mouse
                    default_ans = 2
                else:
                    cur_node = cat
                    default_ans = 1
                ans = default_ans
                for next_node in graph[cur_node]:
                    if cur_node == cat and next_node == 0:
                        continue
                    if cur_node == mouse:
                        next_mouse = next_node
                        next_cat = cat
                    else:
                        next_mouse = mouse
                        next_cat = next_node
                    next_ans = get_result(next_mouse, next_cat, turns + 1)
                    if next_ans != default_ans:
                        ans = next_ans
                        if ans != 0:
                            break
            dp[mouse][cat][turns] = ans
            return dp[mouse][cat][turns]

        return get_result(1, 2, 0)
